-- Education: names and fees are configurable by the King; no invented institutions.
CREATE TABLE education_institutions (id TEXT PRIMARY KEY, name TEXT NOT NULL, level TEXT NOT NULL CHECK(level IN ('primary','middle','secondary','university')), sector TEXT NOT NULL CHECK(sector IN ('public','private')), capacity INTEGER NOT NULL CHECK(capacity>0), min_grade REAL NOT NULL DEFAULT 55 CHECK(min_grade BETWEEN 0 AND 100), fee INTEGER NOT NULL DEFAULT 0 CHECK(fee>=0), active INTEGER NOT NULL DEFAULT 1 CHECK(active IN (0,1)), created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE education_applications (id TEXT PRIMARY KEY, institution_id TEXT NOT NULL REFERENCES education_institutions(id), student_id TEXT NOT NULL REFERENCES users(id), guardian_id TEXT REFERENCES users(id), previous_grade REAL CHECK(previous_grade BETWEEN 0 AND 100), status TEXT NOT NULL DEFAULT 'submitted' CHECK(status IN ('submitted','accepted','rejected')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, reviewed_by TEXT REFERENCES users(id), reviewed_at TEXT, UNIQUE(institution_id,student_id));
CREATE INDEX education_app_status ON education_applications(institution_id,status);
CREATE TABLE education_grades (id TEXT PRIMARY KEY, application_id TEXT NOT NULL REFERENCES education_applications(id), original_grade REAL NOT NULL CHECK(original_grade BETWEEN 0 AND 100), retest_grade REAL CHECK(retest_grade BETWEEN 0 AND 100), recorded_by TEXT NOT NULL REFERENCES users(id), updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(application_id));
